#include <iostream>

auto make_offset(int offset) {
    // TODO: conserva una copia di offset nella closure restituita.
    return [offset](int x) { return x + offset; };
}

int main() {
    int base=0, x=0, delta=0;
    std::cin >> base >> x >> delta;
    auto snapshot = make_offset(base);
    // TODO: osserva la variabile base originale, viva fino a fine main.
    auto live = [&base](int value) { return value + base; };
    base += delta;
    std::cout << snapshot(x) << ' ' << live(x) << '\n';
}

